{
  "scenario_id": "sc-3c83fd",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "CI",
      "years": [2017, 2024],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "A/E declined to 0.73–0.81 in 2018–2019, then jumped ~+0.30 in 2020 to ~1.07 and held 1.06–1.10 through 2024; end level +0.06 above line mean",
      "confidence": 0.75,
      "evidence": [
        "ae_ci_by_year.csv: 2017=0.927, 2018=0.808, 2019=0.731, 2020=1.067, 2021=1.100, 2022=1.084, 2023=1.090, 2024=1.055",
        "Evidence pack: step +0.156 at 2020; 2018–2019 excursion −0.290 (score 6.7); onset ratio 1.16 (level change arrives in one year, not a build-up); end level +0.058 vs baseline (clean lines ≤ 0.008)",
        "Five consecutive years (2020–2024) with A/E ≥ 1.055, well above the ~1.00 baseline; overdispersion x4.73 makes per-year z-scores indicative only, but the sustained multi-year offset is not consistent with noise"
      ],
      "recommended_action": "Investigate the CI experience level shift around 2019–2020: review for changes in CI definition or covered-condition lists, diagnosis/coding practice changes, claim-adjudication or triage policy changes, new product features, or data-quality issues (e.g., a one-time system migration). Determine whether the 2018–2019 undershoot and the 2020+ overshoot are mirror images of a data/coding event or a genuine change in claim frequency. If genuine, quantify the impact on pricing, reserving, and experience-rating assumptions."
    }
  ]
}

